            EqualsMaskHelper.Include include = EqualsMaskHelper.Include.All)
        {
            ret.EDID = string.Equals(item.EDID, rhs.EDID);
            ret.RCLR = item.RCLR == rhs.RCLR;
            ret.Worldspace = item.Worldspace.Equals(rhs.Worldspace);
            ret.Location = item.Location.Equals(rhs.Location);
            ret.LCPR = item.LCPR == rhs.LCPR;
            ret.RCBN = item.RCBN == rhs.RCBN;
            ret.ANAM = item.ANAM.EqualsWithin(rhs.ANAM);
