            ret.RDMO = item.RDMO.EqualsWithin(rhs.RDMO);
            ret.RDMP = item.RDMP == rhs.RDMP;
            ret.RDOT = MemorySliceExt.SequenceEqual(item.RDOT, rhs.RDOT);
            ret.RDSN = MemorySliceExt.SequenceEqual(item.RDSN, rhs.RDSN);
            ret.RDWK = item.RDWK.Equals(rhs.RDWK);
            ret.RDWR = item.RDWR == rhs.RDWR;
            ret.RLDM = MemorySliceExt.SequenceEqual(item.RLDM, rhs.RLDM);
            ret.DataHeaders = item.DataHeaders.CollectionEqualsHelper(
                rhs.DataHeaders,
                (loqLhs, loqRhs) => loqLhs.GetEqualsMask(loqRhs, include),
                include);
            ret.RDSA = MemorySliceExt.SequenceEqual(item.RDSA, rhs.RDSA);
            ret.RDWT = MemorySliceExt.SequenceEqual(item.RDWT, rhs.RDWT);
            ret.RPLD = MemorySliceExt.SequenceEqual(item.RPLD, rhs.RPLD);
