        partial void CustomFactoryEnd(
            OverlayStream stream,
            int finalPos,
            int offset);

        partial void CustomCtor();
        protected RegionBinaryOverlay(
            MemoryPair memoryPair,
            BinaryOverlayFactoryPackage package)
            : base(
                memoryPair: memoryPair,
                package: package)
        {
            this.CustomCtor();
        }

        public static IRegionGetter RegionFactory(
            OverlayStream stream,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            stream = Decompression.DecompressStream(stream);
            stream = ExtractRecordMemory(
                stream: stream,
                meta: package.MetaData.Constants,
                memoryPair: out var memoryPair,
                offset: out var offset,
                finalPos: out var finalPos);
            var ret = new RegionBinaryOverlay(
                memoryPair: memoryPair,
                package: package);
            ret._package.FormVersion = ret;
            ret.CustomFactoryEnd(
                stream: stream,
                finalPos: finalPos,
                offset: offset);
            ret.FillSubrecordTypes(
                majorReference: ret,
                stream: stream,
                finalPos: finalPos,
                offset: offset,
                translationParams: translationParams,
                fill: ret.FillRecordType);
            return ret;
        }

        public static IRegionGetter RegionFactory(
            ReadOnlyMemorySlice<byte> slice,
            BinaryOverlayFactoryPackage package,
            TypedParseParams translationParams = default)
        {
            return RegionFactory(
                stream: new OverlayStream(slice, package),
                package: package,
                translationParams: translationParams);
        }

        public override ParseResult FillRecordType(
            OverlayStream stream,
            int finalPos,
            int offset,
            RecordType type,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            TypedParseParams translationParams = default)
        {
            type = translationParams.ConvertToStandard(type);
            switch (type.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return base.FillRecordType(
                            stream: stream,
                            finalPos: finalPos,
                            offset: offset,
                            type: type,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        _EDIDLocation = (stream.Position - offset);
                        return new ParseResult((int)Region_FieldIndex.EDID, type);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(type) ?? 0)
                        {
                            case 0:
                            {
                                return base.FillRecordType(
                                    stream: stream,
                                    finalPos: finalPos,
                                    offset: offset,
                                    type: type,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    translationParams: translationParams.WithNoConverter());
                            }
                            case 1:
                            {
                                _EDIDLocation = (stream.Position - offset);
                                return new ParseResult((int)Region_FieldIndex.EDID, type);
                            }
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.RCLR:
                {
                    _RCLRLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RCLR;
                }
                case RecordTypeInts.WNAM:
                {
                    _WorldspaceLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.Worldspace;
                }
                case RecordTypeInts.LNAM:
                {
                    _LocationLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.Location;
                }
                case RecordTypeInts.LCPR:
                {
                    _LCPRLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.LCPR;
                }
                case RecordTypeInts.RCBN:
                {
                    _RCBNLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RCBN;
                }
                case RecordTypeInts.ANAM:
                {
                    _ANAMLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.ANAM;
                }
                case RecordTypeInts.ICON:
                {
                    _ICONLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.ICON;
                }
                case RecordTypeInts.RDMO:
                {
                    _RDMOLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDMO;
                }
                case RecordTypeInts.RDMP:
                {
                    _RDMPLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDMP;
                }
                case RecordTypeInts.RDOT:
                {
                    _RDOTLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDOT;
                }
                case RecordTypeInts.RDSN:
                {
                    _RDSNLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDSN;
                }
                case RecordTypeInts.RDWK:
                {
                    _RDWKLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDWK;
                }
                case RecordTypeInts.RDWR:
                {
                    _RDWRLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDWR;
                }
                case RecordTypeInts.RLDM:
                {
                    _RLDMLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RLDM;
                }
                case RecordTypeInts.RDAT:
                {
                    this.DataHeaders = BinaryOverlayList.FactoryByArray<IRegionDataHeaderGetter>(
                        mem: stream.RemainingMemory,
                        package: _package,
                        translationParams: translationParams,
                        getter: (s, p, recConv) => RegionDataHeaderBinaryOverlay.RegionDataHeaderFactory(new OverlayStream(s, p), p, recConv),
                        locs: ParseRecordLocations(
                            stream: stream,
                            trigger: RegionDataHeader_Registration.TriggerSpecs,
                            triggersAlwaysAreNewRecords: true,
                            constants: _package.MetaData.Constants.SubConstants,
                            skipHeader: false));
                    return (int)Region_FieldIndex.DataHeaders;
                }
                case RecordTypeInts.RDSA:
                {
                    _RDSALocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDSA;
                }
                case RecordTypeInts.RDWT:
                {
                    _RDWTLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RDWT;
                }
                case RecordTypeInts.RPLD:
                {
                    _RPLDLocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RPLD;
                }
                case RecordTypeInts.RPLI:
                {
                    _RPLILocation = (stream.Position - offset);
                    return (int)Region_FieldIndex.RPLI;
                }
                default:
                    return base.FillRecordType(
                        stream: stream,
                        finalPos: finalPos,
                        offset: offset,
                        type: type,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        translationParams: translationParams.WithNoConverter());
            }
        }
